insert into public.country_occupation_profiles(profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values('AU:environmental-engineer','AU','environmental-engineer','Environmental Engineer','OSCA','2024 v1.0','2439','AUD',true,'State or territory professional-engineer registration may apply; Engineers Australia (EA) is the migration skills assessing authority','https://www.engineersaustralia.org.au/migrants','profile_ready','2026-08-08',now()) on conflict(profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots(profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values('AU:environmental-engineer','2026-05-01',1600,null,null,null,1852,18,36,36,42,350,'2026-05-01',11.23,12.41,22.96,20,0,5,5,13,0,5,10,3,61,'career-opportunity-v1','provisional',jsonb_build_object('current_classification_scope','Current OSCA 243935 Environmental Engineer assesses environmental impacts for engineering projects and develops solutions for long-term environmental sustainability, including equipment and processes for waste treatment and safe disposal. ABS assigns Skill Level 1 and explicitly excludes Environmental Consultant from this occupation.','legacy_mapping','ANZSCO 233915 Environmental Engineer retains the same title and materially aligned professional scope and remains the Engineers Australia migration occupation. This supports use of the JSA six-digit employment and demographic profile as occupation-specific context.','exact_legacy_233915_context',jsonb_build_object('employment_total',1600,'part_time_share_pct',18,'female_share_pct',36,'median_age',36,'average_full_time_hours',42,'data_as_at','2026-02-01','scope','JSA six-digit ANZSCO 233915 Environmental Engineer; directly title- and scope-aligned with current OSCA 243935'),'broader_anzsco_2339_context',jsonb_build_object('employment_total',20600,'median_weekly_earnings_aud',2649,'median_hourly_earnings_aud',70,'part_time_share_pct',6,'female_share_pct',19,'median_age',35,'average_full_time_hours',42,'scope','ANZSCO 2339 Other Engineering Professionals; substantially broader than Environmental Engineer'),'earnings_scope','JSA does not publish six-digit earnings for ANZSCO 233915. The previous estimated Environmental Engineer salary is removed. Broader ANZSCO 2339 earnings are retained only as context, so the salary component remains zero.','vacancy_scope','The May 2026 IVI three-month-average value of 350 and state vacancy values are published at broader ANZSCO 2339. May 2025 was 314.66667, giving about +11.23% year-on-year. Vacancy intensity is not scored because the vacancy numerator is broader than the exact occupation; the positive broader trend receives partial credit.','projection_scope','JSA Employment Projections for broader ANZSCO 2339 are +12.41% from May 2025 to May 2030 and +22.96% to May 2035. These values receive partial growth credit because the group includes multiple other engineering professions.','shortage_note','The reviewed JSA 2025 Occupation Shortage List records current OSCA 243935 Environmental Engineer as Shortage nationally and in all eight states and territories. The shortage score therefore receives full credit.','visa_basis','The current Core Skills Occupation List includes ANZSCO 233915 Environmental Engineer with Engineers Australia as the relevant assessing authority. Occupation-list inclusion does not determine individual visa eligibility.','registration_basis','ABS notes registration or licensing may be required. Professional-engineer registration requirements vary by state, territory and engineering service. Engineers Australia migration skills assessment is separate from domestic professional registration.','entry_level_basis','RMIT offers a four-year Bachelor of Engineering (Environmental Engineering) (Honours) and a two-year Master of Engineering (Environmental Engineering), both with current Engineers Australia accreditation.','entry_burden_basis','OSCA assigns Skill Level 1. Professional engineering practice generally requires a four-year professional engineering qualification or equivalent competency, and state or territory registration can add an additional requirement depending on the role and jurisdiction.','employer_diversity_basis','Curated coverage spans engineering and environmental consulting, water and waste infrastructure, resources, government and environmental services.','score_note','Environmental Engineer receives full national shortage credit and verified CSOL credit. Exact employment is retained, exact earnings remain unavailable, broader 2339 vacancy growth and long-run projections receive partial credit, and direct accredited study routes support strong entry-level credit.'),'2026-08-08') on conflict(profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
